// Procedural WebAudio: synthwave soundtrack, engine, boost and impacts.
export class AudioEngine {
  constructor() {
    this.ctx = null
    this.started = false
    this.musicOn = true
    this.sfxOn = true
    this.engine = null
    this.musicTimer = null
    this.step = 0
    this.nextNoteTime = 0
    this.tempo = 112
    this.theme = 'city'
    this.master = null
    this.musicGain = null
    this.sfxGain = null
    this.noiseBuffer = null
    this.muted = false
  }

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return }
    try {
      const AC = window.AudioContext || window.webkitAudioContext
      this.ctx = new AC()
      this.master = this.ctx.createGain()
      this.master.gain.value = 0.8
      this.master.connect(this.ctx.destination)
      this.musicGain = this.ctx.createGain()
      this.musicGain.gain.value = this.musicOn ? 0.24 : 0
      this.musicGain.connect(this.master)
      this.sfxGain = this.ctx.createGain()
      this.sfxGain.gain.value = this.sfxOn ? 0.5 : 0
      this.sfxGain.connect(this.master)
      this.noiseBuffer = this.makeNoise(2)
      this.started = true
      this.startMusic()
    } catch (e) { console.warn('Audio unavailable', e) }
  }

  makeNoise(seconds) {
    const ctx = this.ctx
    const buf = ctx.createBuffer(1, ctx.sampleRate * seconds, ctx.sampleRate)
    const d = buf.getChannelData(0)
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1
    return buf
  }

  setSettings({ music, sfx }) {
    if (typeof music === 'boolean') {
      this.musicOn = music
      if (this.musicGain) this.musicGain.gain.setTargetAtTime(music ? 0.24 : 0, this.ctx.currentTime, 0.1)
    }
    if (typeof sfx === 'boolean') {
      this.sfxOn = sfx
      if (this.sfxGain) this.sfxGain.gain.setTargetAtTime(sfx ? 0.5 : 0, this.ctx.currentTime, 0.1)
    }
  }

  setTheme(theme) {
    this.theme = theme
    const themes = {
      city: { tempo: 116, root: 45, scale: [0, 3, 5, 7, 10] },
      underground: { tempo: 100, root: 41, scale: [0, 2, 3, 7, 8] },
      quantum: { tempo: 124, root: 47, scale: [0, 2, 5, 7, 9] },
      ice: { tempo: 92, root: 43, scale: [0, 2, 4, 7, 9] },
      lava: { tempo: 132, root: 40, scale: [0, 1, 5, 6, 8] },
      ruin: { tempo: 96, root: 38, scale: [0, 3, 5, 6, 10] },
      void: { tempo: 88, root: 36, scale: [0, 2, 3, 5, 7] },
      space: { tempo: 90, root: 44, scale: [0, 2, 4, 6, 9] },
      dark: { tempo: 84, root: 34, scale: [0, 1, 3, 6, 8] },
      forest: { tempo: 104, root: 45, scale: [0, 2, 5, 7, 10] },
      desert: { tempo: 110, root: 41, scale: [0, 1, 4, 5, 7] },
      dome: { tempo: 128, root: 40, scale: [0, 3, 5, 7, 10] },
      team: { tempo: 118, root: 45, scale: [0, 3, 5, 7, 10] },
      tunnel: { tempo: 136, root: 42, scale: [0, 2, 3, 7, 10] },
      highway: { tempo: 122, root: 43, scale: [0, 3, 5, 7, 10] },
      solar: { tempo: 114, root: 46, scale: [0, 2, 5, 7, 9] },
      zero: { tempo: 106, root: 37, scale: [0, 2, 3, 6, 10] },
      menu: { tempo: 104, root: 45, scale: [0, 3, 5, 7, 10] },
    }
    this.track = themes[theme] || themes.city
    this.tempo = this.track.tempo
  }

  startMusic() {
    if (!this.ctx || this.musicTimer) return
    this.nextNoteTime = this.ctx.currentTime + 0.08
    this.musicTimer = setInterval(() => this.scheduler(), 30)
  }

  stopMusic() {
    if (this.musicTimer) clearInterval(this.musicTimer)
    this.musicTimer = null
  }

  scheduler() {
    if (!this.ctx || !this.musicOn) return
    const ahead = 0.12
    while (this.nextNoteTime < this.ctx.currentTime + ahead) {
      this.scheduleStep(this.step, this.nextNoteTime)
      this.nextNoteTime += 60 / this.tempo / 4
      this.step = (this.step + 1) % 64
    }
  }

  midi(n) { return 440 * Math.pow(2, (n - 69) / 12) }

  scheduleStep(step, time) {
    if (!this.ctx) return
    const tr = this.track || { root: 45, scale: [0, 3, 5, 7, 10] }
    const bar = Math.floor(step / 16)
    const s = step % 16
    const chordRoots = [0, 5, 3, 7]
    const root = tr.root + chordRoots[bar % 4]
    // kick
    if (s % 4 === 0) this.kick(time, s === 0 ? 0.9 : 0.55)
    // snare / clap
    if (s === 4 || s === 12) this.snare(time, 0.24)
    // hats
    if (s % 2 === 1) this.hat(time, 0.05 + (s % 4 === 3 ? 0.03 : 0))
    // bass
    if (s % 2 === 0) {
      const n = root - 12 + (s === 6 || s === 14 ? 3 : 0)
      this.bass(time, this.midi(n), 0.16, 60 / this.tempo / 2)
    }
    // arp
    if (s % 2 === 0 || s === 7 || s === 15) {
      const deg = tr.scale[(step * 3 + bar) % tr.scale.length]
      const oct = 12 * (1 + ((step + bar) % 3 === 0 ? 1 : 0))
      this.arp(time, this.midi(root + 12 + deg + oct), 0.06, 60 / this.tempo / 3)
    }
    // pad at bar start
    if (s === 0) {
      this.pad(time, [root, root + tr.scale[2], root + tr.scale[4], root + 12], 60 / this.tempo * 3.6)
    }
  }

  env(gain, time, a, d, peak = 1) {
    gain.gain.setValueAtTime(0.0001, time)
    gain.gain.linearRampToValueAtTime(peak, time + a)
    gain.gain.exponentialRampToValueAtTime(0.0001, time + a + d)
  }

  kick(time, vol) {
    const o = this.ctx.createOscillator(), g = this.ctx.createGain()
    o.type = 'sine'
    o.frequency.setValueAtTime(140, time)
    o.frequency.exponentialRampToValueAtTime(38, time + 0.14)
    this.env(g, time, 0.005, 0.24, vol * 0.7)
    o.connect(g).connect(this.musicGain)
    o.start(time); o.stop(time + 0.3)
  }

  snare(time, vol) {
    const src = this.ctx.createBufferSource(), g = this.ctx.createGain(), f = this.ctx.createBiquadFilter()
    src.buffer = this.noiseBuffer
    f.type = 'highpass'; f.frequency.value = 1600
    this.env(g, time, 0.003, 0.16, vol)
    src.connect(f).connect(g).connect(this.musicGain)
    src.start(time); src.stop(time + 0.2)
  }

  hat(time, vol) {
    const src = this.ctx.createBufferSource(), g = this.ctx.createGain(), f = this.ctx.createBiquadFilter()
    src.buffer = this.noiseBuffer
    f.type = 'highpass'; f.frequency.value = 7000
    this.env(g, time, 0.002, 0.05, vol)
    src.connect(f).connect(g).connect(this.musicGain)
    src.start(time); src.stop(time + 0.08)
  }

  bass(time, freq, vol, dur) {
    const o = this.ctx.createOscillator(), g = this.ctx.createGain(), f = this.ctx.createBiquadFilter()
    o.type = 'sawtooth'; o.frequency.value = freq
    f.type = 'lowpass'; f.frequency.value = 340; f.Q.value = 6
    this.env(g, time, 0.01, dur, vol)
    o.connect(f).connect(g).connect(this.musicGain)
    o.start(time); o.stop(time + dur + 0.05)
  }

  arp(time, freq, vol, dur) {
    const o = this.ctx.createOscillator(), g = this.ctx.createGain(), f = this.ctx.createBiquadFilter()
    o.type = 'square'; o.frequency.value = freq
    f.type = 'lowpass'; f.frequency.setValueAtTime(2200, time); f.frequency.exponentialRampToValueAtTime(700, time + dur)
    this.env(g, time, 0.005, dur, vol)
    o.connect(f).connect(g).connect(this.musicGain)
    o.start(time); o.stop(time + dur + 0.02)
  }

  pad(time, notes, dur) {
    for (const n of notes) {
      const o = this.ctx.createOscillator(), g = this.ctx.createGain()
      o.type = 'triangle'; o.frequency.value = this.midi(n)
      g.gain.setValueAtTime(0.0001, time)
      g.gain.linearRampToValueAtTime(0.035, time + 0.4)
      g.gain.linearRampToValueAtTime(0.0001, time + dur)
      o.connect(g).connect(this.musicGain)
      o.start(time); o.stop(time + dur + 0.05)
    }
  }

  // -------------------------------------------------------------------------
  // Engine
  // -------------------------------------------------------------------------
  startEngine(category = 'classic') {
    if (!this.ctx) return
    this.stopEngine()
    const profiles = {
      classic: { type: 'sawtooth', base: 55, cut: 600, sub: 0.4 },
      speed: { type: 'sawtooth', base: 72, cut: 950, sub: 0.5 },
      heavy: { type: 'square', base: 42, cut: 420, sub: 0.7 },
      racing: { type: 'sawtooth', base: 64, cut: 820, sub: 0.45 },
      experimental: { type: 'triangle', base: 84, cut: 1200, sub: 0.35 },
      stealth: { type: 'sine', base: 60, cut: 380, sub: 0.3 },
      legendary: { type: 'sawtooth', base: 68, cut: 1000, sub: 0.5 },
      prototype: { type: 'triangle', base: 78, cut: 1100, sub: 0.4 },
      limited: { type: 'sawtooth', base: 70, cut: 900, sub: 0.5 },
    }
    const pr = profiles[category] || profiles.classic
    const ctx = this.ctx
    const out = ctx.createGain()
    out.gain.value = 0
    const filter = ctx.createBiquadFilter()
    filter.type = 'lowpass'; filter.frequency.value = pr.cut; filter.Q.value = 5
    const o1 = ctx.createOscillator(); o1.type = pr.type; o1.frequency.value = pr.base
    const o2 = ctx.createOscillator(); o2.type = 'sawtooth'; o2.frequency.value = pr.base * 1.5
    const sub = ctx.createOscillator(); sub.type = 'sine'; sub.frequency.value = pr.base * 0.5
    const subG = ctx.createGain(); subG.gain.value = pr.sub
    const o2G = ctx.createGain(); o2G.gain.value = 0.35
    o1.connect(filter); o2.connect(o2G).connect(filter); sub.connect(subG).connect(filter)
    filter.connect(out).connect(this.sfxGain)
    o1.start(); o2.start(); sub.start()
    out.gain.setTargetAtTime(0.055, ctx.currentTime, 0.3)
    this.engine = { o1, o2, sub, filter, out, base: pr.base, speed: 0, boost: 0 }
  }

  updateEngine(speed01, boosting, throttle = 1) {
    const e = this.engine
    if (!e || !this.ctx) return
    const t = this.ctx.currentTime
    const freq = e.base * (1 + speed01 * 1.9 + (boosting ? 0.45 : 0))
    e.o1.frequency.setTargetAtTime(freq, t, 0.05)
    e.o2.frequency.setTargetAtTime(freq * 1.5, t, 0.05)
    e.sub.frequency.setTargetAtTime(freq * 0.5, t, 0.05)
    e.filter.frequency.setTargetAtTime(420 + speed01 * 1500 + (boosting ? 900 : 0), t, 0.08)
    e.out.gain.setTargetAtTime(0.03 + speed01 * 0.05 + (boosting ? 0.02 : 0), t, 0.1)
  }

  stopEngine() {
    if (!this.engine || !this.ctx) return
    const e = this.engine
    e.out.gain.setTargetAtTime(0, this.ctx.currentTime, 0.08)
    setTimeout(() => {
      try { e.o1.stop(); e.o2.stop(); e.sub.stop() } catch {}
    }, 400)
    this.engine = null
  }

  // -------------------------------------------------------------------------
  // SFX
  // -------------------------------------------------------------------------
  tone(freq, dur, type = 'sine', vol = 0.2, slide = 0) {
    if (!this.ctx || !this.sfxOn) return
    const t = this.ctx.currentTime
    const o = this.ctx.createOscillator(), g = this.ctx.createGain()
    o.type = type; o.frequency.setValueAtTime(freq, t)
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur)
    g.gain.setValueAtTime(0.0001, t)
    g.gain.linearRampToValueAtTime(vol, t + 0.008)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    o.connect(g).connect(this.sfxGain)
    o.start(t); o.stop(t + dur + 0.02)
  }

  noise(dur, vol = 0.2, hp = 400, lp = 6000) {
    if (!this.ctx || !this.sfxOn) return
    const t = this.ctx.currentTime
    const src = this.ctx.createBufferSource(), g = this.ctx.createGain()
    const f1 = this.ctx.createBiquadFilter(), f2 = this.ctx.createBiquadFilter()
    src.buffer = this.noiseBuffer
    f1.type = 'highpass'; f1.frequency.value = hp
    f2.type = 'lowpass'; f2.frequency.value = lp
    g.gain.setValueAtTime(vol, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    src.connect(f1).connect(f2).connect(g).connect(this.sfxGain)
    src.start(t); src.stop(t + dur + 0.02)
  }

  click() { this.tone(880, 0.05, 'square', 0.06, 220) }
  hover() { this.tone(1320, 0.03, 'sine', 0.025) }
  back() { this.tone(440, 0.08, 'triangle', 0.06, -120) }
  error() { this.tone(160, 0.18, 'square', 0.09, -40) }
  buy() { this.tone(660, 0.08, 'triangle', 0.12); setTimeout(() => this.tone(990, 0.12, 'triangle', 0.1), 70) }
  equip() { this.tone(520, 0.06, 'square', 0.08); setTimeout(() => this.tone(780, 0.09, 'square', 0.07), 60) }
  countdown(final = false) { this.tone(final ? 1320 : 660, final ? 0.45 : 0.16, 'square', 0.14) }
  boost() {
    this.noise(0.5, 0.3, 300, 8000)
    this.tone(180, 0.45, 'sawtooth', 0.12, 900)
  }
  jump() { this.tone(300, 0.22, 'sine', 0.1, 500) }
  drift() { this.noise(0.12, 0.05, 2000, 9000) }
  trailHit() { this.noise(0.3, 0.35, 120, 3000); this.tone(90, 0.3, 'sawtooth', 0.2, -50) }
  crash() {
    this.noise(0.7, 0.55, 60, 4000)
    this.tone(120, 0.6, 'sawtooth', 0.28, -90)
    setTimeout(() => this.noise(0.5, 0.25, 200, 2500), 90)
  }
  explode() {
    this.noise(1.1, 0.6, 40, 3500)
    this.tone(70, 0.9, 'sine', 0.3, -40)
  }
  pickup() { this.tone(990, 0.07, 'triangle', 0.1); setTimeout(() => this.tone(1480, 0.12, 'triangle', 0.09), 60) }
  levelUp() {
    [523, 659, 784, 1046].forEach((f, i) => setTimeout(() => this.tone(f, 0.25, 'triangle', 0.12), i * 110))
  }
  win() {
    [523, 659, 784, 1046, 1318].forEach((f, i) => setTimeout(() => this.tone(f, 0.5, 'triangle', 0.13), i * 140))
  }
  lose() {
    [440, 392, 330, 262].forEach((f, i) => setTimeout(() => this.tone(f, 0.35, 'sawtooth', 0.08), i * 150))
  }
  achievement() {
    [784, 988, 1175, 1568].forEach((f, i) => setTimeout(() => this.tone(f, 0.3, 'square', 0.07), i * 90))
  }
}

export const audio = new AudioEngine()

// Procedural light-cycle and rider models.
import * as THREE from 'three'
import { COSMETIC_MAP, BIKE_MAP } from './data.js'

const decalCache = new Map()
const glowTexCache = new Map()

const wheelRadii = { small: 0.46, medium: 0.56, large: 0.66 }

function glowTexture(color) {
  if (glowTexCache.has(color)) return glowTexCache.get(color)
  const c = document.createElement('canvas')
  c.width = c.height = 128
  const g = c.getContext('2d')
  const grd = g.createRadialGradient(64, 64, 4, 64, 64, 64)
  grd.addColorStop(0, color)
  grd.addColorStop(0.35, color + 'aa')
  grd.addColorStop(1, color + '00')
  g.fillStyle = grd
  g.fillRect(0, 0, 128, 128)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  glowTexCache.set(color, tex)
  return tex
}

function decalTexture(style, color) {
  const key = style + color
  if (decalCache.has(key)) return decalCache.get(key)
  const c = document.createElement('canvas')
  c.width = 256; c.height = 128
  const g = c.getContext('2d')
  g.clearRect(0, 0, 256, 128)
  g.strokeStyle = color
  g.fillStyle = color
  g.lineWidth = 4
  g.shadowColor = color
  g.shadowBlur = 8
  if (style === 'stripes') {
    for (let i = -2; i < 8; i++) {
      g.beginPath(); g.moveTo(i * 44, 128); g.lineTo(i * 44 + 60, 0); g.stroke()
    }
  } else if (style === 'chevrons') {
    for (let i = 0; i < 4; i++) {
      const x = 28 + i * 56
      g.beginPath(); g.moveTo(x, 30); g.lineTo(x + 26, 64); g.lineTo(x, 98); g.stroke()
    }
  } else if (style === 'glyph') {
    for (let i = 0; i < 7; i++) {
      const x = 18 + i * 34
      g.strokeRect(x, 30 + (i % 3) * 14, 16, 16)
      g.beginPath(); g.moveTo(x + 8, 46); g.lineTo(x + 8, 78); g.stroke()
    }
  } else if (style === 'hazard') {
    for (let i = -3; i < 10; i++) {
      g.beginPath(); g.moveTo(i * 34, 128); g.lineTo(i * 34 + 30, 0); g.lineTo(i * 34 + 46, 0); g.lineTo(i * 34 + 16, 128); g.fill()
    }
  } else if (style === 'circuit') {
    for (let i = 0; i < 6; i++) {
      const y = 22 + i * 16
      g.beginPath(); g.moveTo(10, y); g.lineTo(60 + i * 24, y); g.lineTo(80 + i * 24, y + 10); g.lineTo(240, y + 10); g.stroke()
      g.beginPath(); g.arc(62 + i * 24, y, 4, 0, Math.PI * 2); g.fill()
    }
  }
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  decalCache.set(key, tex)
  return tex
}

const darkMetal = () => new THREE.MeshStandardMaterial({ color: '#0b0f16', metalness: 0.92, roughness: 0.32 })
const tyreMat = () => new THREE.MeshStandardMaterial({ color: '#05060a', metalness: 0.2, roughness: 0.9 })

function neonMat(color, intensity = 2.6) {
  return new THREE.MeshStandardMaterial({
    color, emissive: color, emissiveIntensity: intensity, metalness: 0.3, roughness: 0.35,
  })
}

function bodyMaterial(color) {
  return new THREE.MeshStandardMaterial({ color, metalness: 0.82, roughness: 0.28, envMapIntensity: 0.8 })
}

function addBox(parent, w, h, d, mat, x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat)
  m.position.set(x, y, z); m.rotation.set(rx, ry, rz)
  parent.add(m)
  return m
}

function buildBody(group, style, primaryMat, accentMat, darkMat) {
  const body = new THREE.Group()
  body.name = 'body'
  const shape = new THREE.Shape()
  // profile in Z (forward) / Y (up), extruded across X
  const profiles = {
    classic: [[1.55, 0.18], [1.42, 0.52], [0.8, 0.66], [0.1, 0.62], [-0.9, 0.6], [-1.5, 0.4], [-1.52, 0.16], [-0.6, 0.06], [0.7, 0.08]],
    aero: [[1.75, 0.12], [1.5, 0.42], [0.9, 0.55], [0.2, 0.5], [-0.9, 0.5], [-1.65, 0.32], [-1.7, 0.1], [-0.4, 0.04], [0.8, 0.04]],
    heavy: [[1.55, 0.25], [1.5, 0.7], [0.8, 0.82], [0.0, 0.8], [-1.0, 0.78], [-1.6, 0.55], [-1.62, 0.2], [-0.5, 0.08], [0.8, 0.1]],
    experimental: [[1.6, 0.2], [1.4, 0.6], [0.7, 0.72], [0.0, 0.55], [-0.8, 0.7], [-1.5, 0.5], [-1.55, 0.18], [-0.4, 0.06], [0.8, 0.08]],
    stealth: [[1.65, 0.1], [1.45, 0.38], [0.8, 0.46], [0.0, 0.44], [-1.0, 0.48], [-1.6, 0.3], [-1.6, 0.1], [-0.4, 0.03], [0.8, 0.04]],
    legendary: [[1.7, 0.2], [1.5, 0.62], [0.8, 0.75], [0.0, 0.66], [-1.0, 0.68], [-1.62, 0.48], [-1.66, 0.18], [-0.5, 0.06], [0.8, 0.08]],
  }
  const pts = profiles[style] || profiles.classic
  shape.moveTo(pts[0][0], pts[0][1])
  for (let i = 1; i < pts.length; i++) shape.lineTo(pts[i][0], pts[i][1])
  shape.closePath()
  const width = style === 'heavy' ? 0.62 : style === 'stealth' ? 0.42 : 0.52
  const geo = new THREE.ExtrudeGeometry(shape, { depth: width, bevelEnabled: true, bevelSize: 0.06, bevelThickness: 0.06, bevelSegments: 2, steps: 1 })
  geo.translate(0, 0, -width / 2)
  geo.rotateY(Math.PI / 2)
  const bodyMesh = new THREE.Mesh(geo, primaryMat)
  bodyMesh.position.y = 0.02
  body.add(bodyMesh)

  // lower hull / belly
  addBox(body, width * 0.8, 0.14, 2.2, darkMat, 0, 0.0, -0.05)

  // seat
  const seat = addBox(body, width * 0.72, 0.12, 0.72, darkMat, 0, 0.66, -0.42)
  seat.rotation.x = -0.06

  // front fork + handlebars
  addBox(body, 0.09, 0.62, 0.09, darkMat, -0.2, 0.44, 1.12, 0.22)
  addBox(body, 0.09, 0.62, 0.09, darkMat, 0.2, 0.44, 1.12, 0.22)
  addBox(body, 0.9, 0.06, 0.07, darkMat, 0, 0.72, 1.0)
  addBox(body, 0.14, 0.06, 0.07, accentMat, -0.44, 0.72, 1.0)
  addBox(body, 0.14, 0.06, 0.07, accentMat, 0.44, 0.72, 1.0)

  // neon spine
  addBox(body, 0.045, 0.045, 1.9, accentMat, 0, 0.74, 0.05)
  addBox(body, 0.04, 0.05, 0.9, accentMat, 0, 0.14, 1.0)
  // side accent rails
  for (const sx of [-1, 1]) {
    addBox(body, 0.035, 0.05, 1.5, accentMat, sx * (width / 2 + 0.02), 0.28, 0.05)
    addBox(body, 0.03, 0.03, 0.5, accentMat, sx * (width / 2 + 0.02), 0.5, 0.62, 0, 0, sx * 0.5)
  }
  // nose light
  addBox(body, 0.3, 0.05, 0.04, accentMat, 0, 0.3, 1.58)
  // rear tail
  addBox(body, 0.4, 0.1, 0.4, darkMat, 0, 0.48, -1.42)
  addBox(body, 0.28, 0.04, 0.28, accentMat, 0, 0.55, -1.58)

  // heavy armour plates
  if (style === 'heavy') {
    for (const sx of [-1, 1]) {
      addBox(body, 0.08, 0.34, 1.1, darkMat, sx * 0.36, 0.45, -0.1, 0, 0, sx * 0.06)
      addBox(body, 0.05, 0.06, 0.9, accentMat, sx * 0.4, 0.55, -0.1)
    }
    addBox(body, 0.8, 0.12, 0.5, darkMat, 0, 0.8, 0.6, 0.1)
  }
  if (style === 'aero') {
    for (const sx of [-1, 1]) {
      const fin = addBox(body, 0.05, 0.28, 0.9, primaryMat, sx * 0.33, 0.5, -0.55, 0, 0, sx * 0.35)
      fin.rotation.y = sx * 0.08
    }
    addBox(body, 0.02, 0.3, 0.5, accentMat, 0, 0.82, -0.9, 0.25)
  }
  if (style === 'experimental') {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.3, 0.035, 8, 24), accentMat)
    ring.position.set(0, 0.5, 0.55); ring.rotation.x = Math.PI / 2
    body.add(ring)
    addBox(body, 0.03, 0.03, 1.6, accentMat, 0, 0.86, -0.2, 0.05)
  }
  if (style === 'legendary') {
    addBox(body, 0.05, 0.18, 0.8, accentMat, 0, 0.88, 0.45, 0.18)
    addBox(body, 0.05, 0.1, 1.4, accentMat, 0, 0.82, -0.6, 0.1)
  }
  if (style === 'stealth') {
    addBox(body, 0.02, 0.04, 1.3, accentMat, 0, 0.5, 0.1)
    addBox(body, 0.36, 0.04, 0.16, accentMat, 0, 0.56, -1.5)
  }
  return { group: body, width }
}

function buildWheel(radius, style, accentMat, darkMat) {
  const g = new THREE.Group()
  const tire = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 0.16, 24, 1, false), tyreMat())
  tire.rotation.z = Math.PI / 2
  g.add(tire)
  const rim = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.72, 0.028, 8, 28), accentMat)
  rim.rotation.y = Math.PI / 2
  g.add(rim)
  if (style === 'disc') {
    const disc = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.68, radius * 0.68, 0.05, 24), darkMat)
    disc.rotation.z = Math.PI / 2
    g.add(disc)
    const ring = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.42, 0.02, 6, 20), accentMat)
    ring.rotation.y = Math.PI / 2
    g.add(ring)
  } else if (style === 'spoke') {
    for (let i = 0; i < 6; i++) {
      const sp = new THREE.Mesh(new THREE.BoxGeometry(0.035, radius * 1.28, 0.05), darkMat)
      sp.rotation.x = (i / 6) * Math.PI
      g.add(sp)
    }
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, 0.2, 12), accentMat)
    hub.rotation.z = Math.PI / 2
    g.add(hub)
  } else if (style === 'halo') {
    const inner = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.42, 0.022, 6, 20), accentMat)
    inner.rotation.y = Math.PI / 2
    g.add(inner)
    for (let i = 0; i < 4; i++) {
      const sp = new THREE.Mesh(new THREE.BoxGeometry(0.03, radius * 0.6, 0.03), accentMat)
      sp.rotation.x = (i / 4) * Math.PI
      sp.position.y = 0
      g.add(sp)
    }
  } else if (style === 'turbine') {
    for (let i = 0; i < 8; i++) {
      const blade = new THREE.Mesh(new THREE.BoxGeometry(0.02, radius * 0.85, 0.16), accentMat)
      blade.rotation.x = (i / 8) * Math.PI * 2
      blade.position.z = 0
      blade.rotation.z = 0.35
      g.add(blade)
    }
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.22, 10), darkMat)
    hub.rotation.z = Math.PI / 2
    g.add(hub)
  } else if (style === 'void') {
    const voidMat = new THREE.MeshBasicMaterial({ color: '#000000', transparent: true, opacity: 0.55 })
    const disc = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.66, radius * 0.66, 0.04, 20), voidMat)
    disc.rotation.z = Math.PI / 2
    g.add(disc)
    const ring2 = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.5, 0.012, 5, 20), accentMat)
    ring2.rotation.y = Math.PI / 2
    g.add(ring2)
  }
  return g
}

function buildRider(rider, colors, accentMat) {
  const g = new THREE.Group()
  const suitColor = rider?.suitColor || '#00e5ff'
  const suitMat = new THREE.MeshStandardMaterial({ color: suitColor, metalness: 0.55, roughness: 0.45, emissive: suitColor, emissiveIntensity: 0.25 })
  const suitDark = new THREE.MeshStandardMaterial({ color: '#0b0f16', metalness: 0.8, roughness: 0.4 })
  const visorMat = new THREE.MeshStandardMaterial({
    color: colors.visor || '#00e5ff', emissive: colors.visor || '#00e5ff',
    emissiveIntensity: 2.4, metalness: 0.9, roughness: 0.1,
  })
  const armorStyle = rider?.armor || 'armor-light'
  const helmetStyle = rider?.helmet || 'helmet-standard'

  // legs
  for (const sx of [-1, 1]) {
    const thigh = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.06, 0.46, 8), suitDark)
    thigh.position.set(sx * 0.18, 0.62, -0.12); thigh.rotation.x = -0.75
    g.add(thigh)
    const shin = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.045, 0.42, 8), suitMat)
    shin.position.set(sx * 0.2, 0.42, 0.05); shin.rotation.x = -1.15
    g.add(shin)
    const boot = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.09, 0.24), suitDark)
    boot.position.set(sx * 0.2, 0.25, 0.18)
    g.add(boot)
  }
  // torso leaning forward
  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.17, 0.38, 6, 10), suitMat)
  torso.position.set(0, 0.98, -0.18); torso.rotation.x = 0.52
  g.add(torso)
  // chest neon
  const chest = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.2, 0.04), accentMat)
  chest.position.set(0, 1.02, 0.02); chest.rotation.x = 0.52
  g.add(chest)
  // arms to bars
  for (const sx of [-1, 1]) {
    const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.04, 0.44, 7), suitMat)
    arm.position.set(sx * 0.27, 0.88, 0.2); arm.rotation.set(1.05, 0, sx * -0.18)
    g.add(arm)
    const hand = new THREE.Mesh(new THREE.SphereGeometry(0.055, 8, 6), suitDark)
    hand.position.set(sx * 0.32, 0.79, 0.44)
    g.add(hand)
  }
  // head + helmet
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.17, 14, 10), helmetStyle === 'helmet-crown' ? suitMat : suitDark)
  head.position.set(0, 1.32, -0.04); head.scale.set(1, 0.95, 1.05)
  g.add(head)
  const visor = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.09, 0.05), visorMat)
  visor.position.set(0, 1.33, 0.13)
  g.add(visor)
  if (helmetStyle === 'helmet-aero') {
    const fin = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.1, 0.24), accentMat)
    fin.position.set(0, 1.44, -0.12); fin.rotation.x = 0.2
    g.add(fin)
  } else if (helmetStyle === 'helmet-horned') {
    for (const sx of [-1, 1]) {
      const horn = new THREE.Mesh(new THREE.ConeGeometry(0.035, 0.22, 6), accentMat)
      horn.position.set(sx * 0.13, 1.44, 0.0); horn.rotation.z = sx * 0.5
      g.add(horn)
    }
  } else if (helmetStyle === 'helmet-crown') {
    for (let i = 0; i < 5; i++) {
      const spike = new THREE.Mesh(new THREE.ConeGeometry(0.025, 0.14, 4), accentMat)
      spike.position.set((i - 2) * 0.07, 1.5, -0.04)
      g.add(spike)
    }
  }
  // armour
  if (armorStyle === 'armor-plated' || armorStyle === 'armor-reactive' || armorStyle === 'armor-legend') {
    for (const sx of [-1, 1]) {
      const pad = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.12, 0.2), suitDark)
      pad.position.set(sx * 0.25, 1.06, -0.1); pad.rotation.x = 0.5
      g.add(pad)
    }
  }
  if (armorStyle === 'armor-legend') {
    const cape = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.42, 0.03), accentMat)
    cape.position.set(0, 0.92, -0.44); cape.rotation.x = -0.18
    g.add(cape)
  }
  if (armorStyle === 'armor-reactive') {
    const line = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.32, 0.03), accentMat)
    line.position.set(0, 1.0, -0.34)
    g.add(line)
  }
  // suit effect aura
  const fx = rider?.suitfx || 'suitfx-none'
  if (fx !== 'suitfx-none') {
    const aura = new THREE.Mesh(
      new THREE.TorusGeometry(0.36, 0.012, 5, 24),
      new THREE.MeshBasicMaterial({ color: suitColor, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending })
    )
    aura.position.set(0, 0.95, -0.1); aura.rotation.x = Math.PI / 2
    aura.name = 'suitAura'
    g.add(aura)
  }
  return g
}

export function createBikeModel(bike, custom, rider, options = {}) {
  const { player = false, detail = true } = options
  const colors = {
    primary: custom?.primary || bike.visual.primary,
    accent: custom?.accent || bike.visual.accent,
    trail: custom?.trail || bike.visual.trail,
    glow: custom?.glow || bike.visual.glow,
  }
  const frameStyle = (COSMETIC_MAP[custom?.frame]?.style) || bike.visual.frame || 'classic'
  const wheelStyle = (COSMETIC_MAP[custom?.wheels]?.style) || bike.visual.wheels || 'disc'
  const wheelSize = custom?.wheelSize || bike.visual.wheelSize || 'medium'
  const radius = wheelRadii[wheelSize] || 0.56

  const group = new THREE.Group()
  group.name = 'lightcycle'
  const primaryMat = bodyMaterial(colors.primary)
  const accentMat = neonMat(colors.accent, 2.8)
  const trailMat = neonMat(colors.trail, 2.2)
  const darkMat = darkMetal()

  const bodyGroup = new THREE.Group()
  bodyGroup.position.y = radius - 0.56
  group.add(bodyGroup)
  const { width } = buildBody(bodyGroup, frameStyle, primaryMat, accentMat, darkMat)

  // decal side panels
  const decalStyle = (COSMETIC_MAP[custom?.decal]?.style) || bike.visual.decal || 'none'
  if (detail && decalStyle !== 'none') {
    const tex = decalTexture(decalStyle, colors.accent)
    const dMat = new THREE.MeshBasicMaterial({ map: tex, transparent: true, opacity: 0.95, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false })
    for (const sx of [-1, 1]) {
      const plane = new THREE.Mesh(new THREE.PlaneGeometry(1.25, 0.42), dMat)
      plane.position.set(sx * (width / 2 + 0.035), 0.42, -0.05)
      plane.rotation.y = sx * Math.PI / 2
      bodyGroup.add(plane)
    }
  }

  // wheels
  const wheels = []
  for (const z of [1.08, -1.1]) {
    const wg = buildWheel(radius, wheelStyle, accentMat, darkMat)
    wg.position.set(0, radius, z)
    group.add(wg)
    wheels.push(wg)
  }
  // wheel glow
  const under = new THREE.Mesh(
    new THREE.PlaneGeometry(2.6, 1.5),
    new THREE.MeshBasicMaterial({ map: glowTexture(colors.glow), transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false })
  )
  under.rotation.x = -Math.PI / 2
  under.position.y = 0.02
  group.add(under)

  // engine core
  const engineStyle = (COSMETIC_MAP[custom?.engine]?.style) || bike.visual.engine || 'core'
  const engineGroup = new THREE.Group()
  engineGroup.position.set(0, 0.5 + radius - 0.56, -1.32)
  const core = new THREE.Mesh(new THREE.SphereGeometry(engineStyle === 'quantum' ? 0.14 : 0.11, 12, 8), trailMat)
  engineGroup.add(core)
  if (engineStyle === 'plasma') {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.17, 0.02, 6, 16), accentMat)
    ring.rotation.x = Math.PI / 2
    engineGroup.add(ring)
  } else if (engineStyle === 'void') {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.2, 0.015, 5, 18), accentMat)
    engineGroup.add(ring)
  }
  const exhaust = new THREE.Mesh(
    new THREE.ConeGeometry(0.09, 0.55, 10, 1, true),
    new THREE.MeshBasicMaterial({ color: colors.trail, transparent: true, opacity: 0.0, blending: THREE.AdditiveBlending, depthWrite: false })
  )
  exhaust.position.z = -0.36; exhaust.rotation.x = Math.PI / 2
  exhaust.name = 'exhaust'
  engineGroup.add(exhaust)
  group.add(engineGroup)

  // rider
  const riderGroup = buildRider(rider, { visor: COSMETIC_MAP[rider?.visor]?.color }, accentMat)
  riderGroup.position.y = radius - 0.56
  group.add(riderGroup)

  // headlight / glow sprite
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTexture(colors.glow), color: colors.glow, transparent: true,
    blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0.8,
  }))
  sprite.scale.set(1.1, 1.1, 1)
  sprite.position.set(0, 0.5 + radius - 0.56, 1.5)
  group.add(sprite)

  let t = 0
  const lightStyle = (COSMETIC_MAP[custom?.lighting]?.style) || bike.visual.lighting || 'pulse'
  const boostStyle = (COSMETIC_MAP[custom?.boost]?.style) || 'flare'

  const model = {
    group, wheels, bodyGroup, riderGroup, colors, radius,
    accentMat, trailMat, primaryMat, darkMat, engineGroup, core, exhaust, sprite,
    lean: 0,
    setVisible(v) { group.visible = v },
    setColors(newColors) {
      if (newColors.primary) primaryMat.color.set(newColors.primary)
      if (newColors.accent) { accentMat.color.set(newColors.accent); accentMat.emissive.set(newColors.accent) }
      if (newColors.trail) { trailMat.color.set(newColors.trail); trailMat.emissive.set(newColors.trail) }
    },
    update(dt, state = {}) {
      t += dt
      const speed = state.speed || 0
      for (const w of wheels) w.rotation.x -= speed * dt * 2.2
      const targetLean = (state.steer || 0) * 0.42
      model.lean += (targetLean - model.lean) * Math.min(1, dt * 8)
      group.rotation.z = model.lean
      riderGroup.rotation.z = -model.lean * 0.35
      bodyGroup.position.y = (radius - 0.56) + Math.sin(t * 8 + speed * 0.1) * 0.012 * (speed > 1 ? 1 : 0.2)
      const boost = state.boosting ? 1 : 0
      if (exhaust) {
        exhaust.material.opacity += ((boost ? 0.85 : 0.0) - exhaust.material.opacity) * Math.min(1, dt * 10)
        exhaust.scale.setScalar(1 + boost * (0.8 + Math.sin(t * 30) * 0.2))
      }
      if (core) core.scale.setScalar(1 + Math.sin(t * 9) * 0.08 + boost * 0.35)
      // animated lighting
      let intensity = 2.6
      if (lightStyle === 'pulse') intensity = 2.3 + Math.sin(t * 3.2) * 0.7
      else if (lightStyle === 'wave') intensity = 2.4 + Math.sin(t * 5 + 0.5) * 0.6
      else if (lightStyle === 'strobe') intensity = 2.0 + (Math.sin(t * 16) > 0.5 ? 2.0 : 0)
      accentMat.emissiveIntensity = intensity + boost * 1.6
      trailMat.emissiveIntensity = 2.2 + Math.sin(t * 4) * 0.3 + boost * 1.2
      if (sprite) sprite.material.opacity = 0.5 + Math.sin(t * 4) * 0.15 + boost * 0.3
      // suit aura
      const aura = riderGroup.getObjectByName('suitAura')
      if (aura) { aura.rotation.z += dt * 1.8; aura.material.opacity = 0.35 + Math.sin(t * 3) * 0.2 }
      // boost effect on group
      if (boostStyle === 'warp' && boost) group.scale.set(1, 1, 1.04)
      else group.scale.set(1, 1, 1)
    },
  }
  return model
}

// Static preview helper: returns a scene ready to render one bike.
export function createPreviewScene(bike, custom, rider, opts = {}) {
  const scene = new THREE.Scene()
  scene.background = null
  const camera = new THREE.PerspectiveCamera(34, 1, 0.1, 100)
  const model = createBikeModel(bike, custom, rider, opts)
  scene.add(model.group)
  const hemi = new THREE.HemisphereLight(0x88ccff, 0x020408, 1.4)
  scene.add(hemi)
  const key = new THREE.DirectionalLight(0xffffff, 2.6)
  key.position.set(3, 5, 4)
  scene.add(key)
  const rim = new THREE.PointLight(0x00e5ff, 20, 12)
  rim.position.set(-3, 1.5, -3)
  scene.add(rim)
  const rim2 = new THREE.PointLight(0xff7a18, 12, 10)
  rim2.position.set(3, 1, -4)
  scene.add(rim2)
  // turntable disc
  const disc = new THREE.Mesh(
    new THREE.CylinderGeometry(2.2, 2.4, 0.1, 48),
    new THREE.MeshStandardMaterial({ color: '#04080f', metalness: 0.9, roughness: 0.25 })
  )
  disc.position.y = -0.02
  scene.add(disc)
  const ring = new THREE.Mesh(
    new THREE.TorusGeometry(2.35, 0.02, 6, 64),
    new THREE.MeshBasicMaterial({ color: custom?.accent || bike.visual.accent })
  )
  ring.rotation.x = Math.PI / 2
  ring.position.y = 0.04
  scene.add(ring)
  return { scene, camera, model, ring }
}

// Procedural track / arena construction and collision helpers.
import * as THREE from 'three'

const tmpV = new THREE.Vector3()

function hash(str) {
  let h = 2166136261 >>> 0
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619) }
  return h >>> 0
}
function seeded(seed) {
  let s = seed >>> 0
  return () => {
    s += 0x6D2B79F5
    let t = s
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function gridTexture(c1, c2, cells = 8, size = 256) {
  const c = document.createElement('canvas')
  c.width = c.height = size
  const g = c.getContext('2d')
  g.fillStyle = '#02050a'
  g.fillRect(0, 0, size, size)
  const step = size / cells
  g.lineWidth = 1
  g.strokeStyle = c1 + '22'
  g.shadowBlur = 4
  g.shadowColor = c1
  for (let i = 1; i < cells; i++) {
    g.beginPath(); g.moveTo(i * step, 0); g.lineTo(i * step, size); g.stroke()
    g.beginPath(); g.moveTo(0, i * step); g.lineTo(size, i * step); g.stroke()
  }
  g.lineWidth = 2.5
  g.strokeStyle = c1
  g.shadowBlur = 10
  g.shadowColor = c1
  g.strokeRect(0, 0, size, size)
  g.strokeStyle = c2 + '88'
  g.lineWidth = 1.5
  g.beginPath(); g.moveTo(step * 0.5, 0); g.lineTo(step * 0.5, size); g.stroke()
  g.beginPath(); g.moveTo(0, step * 0.5); g.lineTo(size, step * 0.5); g.stroke()
  const tex = new THREE.CanvasTexture(c)
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.colorSpace = THREE.SRGBColorSpace
  tex.anisotropy = 4
  return tex
}

function checkerTexture(a = '#e2e8f0', b = '#0b0f16') {
  const c = document.createElement('canvas')
  c.width = 128; c.height = 128
  const g = c.getContext('2d')
  for (let y = 0; y < 4; y++) for (let x = 0; x < 4; x++) {
    g.fillStyle = (x + y) % 2 ? a : b
    g.fillRect(x * 32, y * 32, 32, 32)
  }
  const tex = new THREE.CanvasTexture(c)
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

function polygonFor(track) {
  const { shape, size } = track
  const rx = size.x, rz = size.z
  if (shape === 'rect') return [[-rx, -rz], [rx, -rz], [rx, rz], [-rx, rz]]
  if (shape === 'diamond') return [[0, -rz], [rx, 0], [0, rz], [-rx, 0]]
  if (shape === 'hex') {
    const pts = []
    for (let i = 0; i < 6; i++) { const a = Math.PI / 6 + i * Math.PI / 3; pts.push([Math.cos(a) * rx, Math.sin(a) * rz]) }
    return pts
  }
  if (shape === 'oct') {
    const pts = []
    for (let i = 0; i < 8; i++) { const a = Math.PI / 8 + i * Math.PI / 4; pts.push([Math.cos(a) * rx, Math.sin(a) * rz]) }
    return pts
  }
  if (shape === 'cross') {
    const a = rx * 0.42, b = rx
    return [[-a, -b], [a, -b], [a, -a], [b, -a], [b, a], [a, a], [a, b], [-a, b], [-a, a], [-b, a], [-b, -a], [-a, -a]]
  }
  // circle
  const pts = []
  const n = 40
  for (let i = 0; i < n; i++) { const a = i / n * Math.PI * 2; pts.push([Math.cos(a) * rx, Math.sin(a) * rz]) }
  return pts
}

function insidePoly(x, z, poly) {
  let inside = false
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i][0], zi = poly[i][1], xj = poly[j][0], zj = poly[j][1]
    if ((zi > z) !== (zj > z) && x < ((xj - xi) * (z - zi)) / (zj - zi) + xi) inside = !inside
  }
  return inside
}

function distToSegment(px, pz, ax, az, bx, bz) {
  const dx = bx - ax, dz = bz - az
  const l2 = dx * dx + dz * dz
  let t = l2 ? ((px - ax) * dx + (pz - az) * dz) / l2 : 0
  t = Math.max(0, Math.min(1, t))
  const x = ax + dx * t, z = az + dz * t
  return Math.hypot(px - x, pz - z)
}

function makeSky(scene, pal, density = 0.0038) {
  scene.background = new THREE.Color(pal.sky)
  scene.fog = new THREE.FogExp2(pal.fog, density)
  const geo = new THREE.SphereGeometry(700, 24, 16)
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false,
    uniforms: {
      top: { value: new THREE.Color(pal.sky) },
      bottom: { value: new THREE.Color(pal.haze) },
      accent: { value: new THREE.Color(pal.accent) },
    },
    vertexShader: `varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
    fragmentShader: `
      varying vec3 vP; uniform vec3 top; uniform vec3 bottom; uniform vec3 accent;
      void main(){
        float h = clamp(vP.y / 700.0 * 1.6 + 0.35, 0.0, 1.0);
        vec3 col = mix(bottom, top, h);
        float band = smoothstep(0.18, 0.0, abs(h - 0.2));
        col += accent * band * 0.08;
        gl_FragColor = vec4(col, 1.0);
      }`,
  })
  const sky = new THREE.Mesh(geo, mat)
  scene.add(sky)
  return sky
}

function makeStars(scene, pal, count = 900) {
  const pos = new Float32Array(count * 3)
  const rnd = seeded(1337)
  for (let i = 0; i < count; i++) {
    const a = rnd() * Math.PI * 2, e = rnd() * Math.PI * 0.45 + 0.05
    const r = 520
    pos[i * 3] = Math.cos(a) * Math.cos(e) * r
    pos[i * 3 + 1] = Math.sin(e) * r
    pos[i * 3 + 2] = Math.sin(a) * Math.cos(e) * r
  }
  const g = new THREE.BufferGeometry()
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3))
  const m = new THREE.PointsMaterial({ color: pal.accent2, size: 1.6, transparent: true, opacity: 0.7, blending: THREE.AdditiveBlending, depthWrite: false })
  const pts = new THREE.Points(g, m)
  scene.add(pts)
  return pts
}

function neonBox(w, h, d, color, opacity = 1) {
  return new THREE.Mesh(
    new THREE.BoxGeometry(w, h, d),
    new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 2.2, metalness: 0.4, roughness: 0.4, transparent: opacity < 1, opacity })
  )
}

export class Track {
  constructor(scene, data, quality = 'medium') {
    this.scene = scene
    this.data = data
    this.pal = data.palette
    this.quality = quality
    this.type = data.type
    this.group = new THREE.Group()
    this.group.name = 'track'
    scene.add(this.group)
    this.hazards = []
    this.obstacles = []
    this.boostPads = []
    this.disposables = []
    this.shrinkScale = 1
    this.time = 0
    this.rnd = seeded(hash(data.id))
    this.enclosed = !!data.enclosed
    this.animated = []

    makeSky(scene, this.pal, data.type === 'circuit' ? 0.0028 : 0.0042)
    if (['space', 'dark', 'void', 'zero'].includes(data.theme)) makeStars(scene, this.pal)

    this.addLights()
    if (this.type === 'circuit') this.buildCircuit()
    else this.buildArena()
    this.addBoostPads()
    this.buildEnvironment()
  }

  addLights() {
    const hemi = new THREE.HemisphereLight(this.pal.accent2, this.pal.ground, 1.1)
    this.scene.add(hemi)
    this.lights = [hemi]
    const dir = new THREE.DirectionalLight(0xffffff, 1.5)
    dir.position.set(-80, 140, 60)
    this.scene.add(dir)
    this.lights.push(dir)
    const p1 = new THREE.PointLight(this.pal.accent, 90, 220, 1.8)
    p1.position.set(0, 28, 0)
    this.scene.add(p1)
    this.lights.push(p1)
    if (this.type === 'arena') {
      const p2 = new THREE.PointLight(this.pal.accent2, 70, 200, 1.8)
      p2.position.set(0, 14, -this.data.size.z * 0.7)
      this.scene.add(p2)
      this.lights.push(p2)
    }
  }

  // -------------------------------------------------------------------------
  // Arena
  // -------------------------------------------------------------------------
  buildArena() {
    const poly = polygonFor(this.data)
    this.poly = poly
    const shape = new THREE.Shape()
    shape.moveTo(poly[0][0], poly[0][1])
    for (let i = 1; i < poly.length; i++) shape.lineTo(poly[i][0], poly[i][1])
    shape.closePath()
    const floorGeo = new THREE.ShapeGeometry(shape, 8)
    floorGeo.rotateX(-Math.PI / 2)
    const tex = gridTexture(this.pal.grid, this.pal.grid2, 8, 256)
    tex.repeat.set(1 / 12, 1 / 12)
    const floorMat = new THREE.MeshStandardMaterial({
      color: this.pal.ground, map: tex, emissive: this.pal.grid, emissiveMap: tex,
      emissiveIntensity: 0.55, metalness: 0.72, roughness: 0.36,
    })
    const floor = new THREE.Mesh(floorGeo, floorMat)
    floor.position.y = 0
    this.group.add(floor)
    this.floor = floor

    // subtle outer glow disc
    const glow = new THREE.Mesh(
      new THREE.CircleGeometry(Math.max(this.data.size.x, this.data.size.z) * 1.5, 48),
      new THREE.MeshBasicMaterial({ color: this.pal.accent, transparent: true, opacity: 0.025, blending: THREE.AdditiveBlending, depthWrite: false })
    )
    glow.rotation.x = -Math.PI / 2
    glow.position.y = -0.05
    this.group.add(glow)

    // boundary walls
    const wallGroup = new THREE.Group()
    this.wallGroup = wallGroup
    this.group.add(wallGroup)
    const h = 3.2
    for (let i = 0; i < poly.length; i++) {
      const a = poly[i], b = poly[(i + 1) % poly.length]
      const dx = b[0] - a[0], dz = b[1] - a[1]
      const len = Math.hypot(dx, dz)
      const ang = Math.atan2(dx, dz)
      const wall = new THREE.Mesh(
        new THREE.BoxGeometry(0.5, h, len),
        new THREE.MeshStandardMaterial({ color: this.pal.ground, metalness: 0.8, roughness: 0.35, emissive: this.pal.accent, emissiveIntensity: 0.12 })
      )
      wall.position.set((a[0] + b[0]) / 2, h / 2, (a[1] + b[1]) / 2)
      wall.rotation.y = ang
      wallGroup.add(wall)
      const line = neonBox(0.08, 0.08, len, this.pal.accent)
      line.position.set((a[0] + b[0]) / 2, h + 0.02, (a[1] + b[1]) / 2)
      line.rotation.y = ang
      wallGroup.add(line)
      const base = neonBox(0.1, 0.04, len, this.pal.accent2)
      base.position.set((a[0] + b[0]) / 2, 0.04, (a[1] + b[1]) / 2)
      base.rotation.y = ang
      wallGroup.add(base)
    }

    // shrink ring (hidden unless shrinking)
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(1, 0.09, 6, 64),
      new THREE.MeshBasicMaterial({ color: '#ff3d81', transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending })
    )
    ring.rotation.x = Math.PI / 2
    ring.position.y = 0.15
    ring.visible = false
    this.shrinkRing = ring
    this.group.add(ring)

    // obstacles
    for (const o of this.data.obstacles || []) this.addObstacle(o)
    // hazards
    for (const hz of this.data.hazards || []) this.addHazard(hz)
  }

  addObstacle(o) {
    const mat = new THREE.MeshStandardMaterial({
      color: this.pal.ground, metalness: 0.85, roughness: 0.3,
      emissive: this.pal.accent2, emissiveIntensity: 0.18,
    })
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(o.w, o.h, o.d), mat)
    mesh.position.set(o.x, o.h / 2, o.z)
    this.group.add(mesh)
    const trim = neonBox(o.w + 0.1, 0.08, o.d + 0.1, this.pal.accent2)
    trim.position.set(o.x, o.h + 0.02, o.z)
    this.group.add(trim)
    const base = neonBox(o.w + 0.2, 0.05, o.d + 0.2, this.pal.accent)
    base.position.set(o.x, 0.04, o.z)
    this.group.add(base)
    this.obstacles.push({ x: o.x, z: o.z, w: o.w, d: o.d, h: o.h, mesh })
  }

  addHazard(hz) {
    const colors = { heat: '#ff4d00', ice: '#67e8f9', glitch: '#d946ef', void: '#7c3aed' }
    const color = colors[hz.type] || '#ff3d81'
    const g = new THREE.Group()
    g.position.set(hz.x, 0, hz.z)
    const disc = new THREE.Mesh(
      new THREE.CircleGeometry(hz.r, 32),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.14, blending: THREE.AdditiveBlending, depthWrite: false })
    )
    disc.rotation.x = -Math.PI / 2
    disc.position.y = 0.03
    g.add(disc)
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(hz.r, 0.1, 6, 48),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending })
    )
    ring.rotation.x = Math.PI / 2
    ring.position.y = 0.06
    g.add(ring)
    for (let i = 0; i < 6; i++) {
      const bar = neonBox(0.05, 0.05, hz.r * 1.3, color, 0.6)
      bar.position.y = 0.08
      bar.rotation.y = i / 6 * Math.PI
      g.add(bar)
    }
    this.group.add(g)
    this.hazards.push({ ...hz, mesh: g, disc, ring, phase: this.rnd() * 10, active: true })
  }

  // -------------------------------------------------------------------------
  // Circuit
  // -------------------------------------------------------------------------
  buildCircuit() {
    const pts = this.data.points.map(p => new THREE.Vector3(p[0], 0, p[1]))
    const curve = new THREE.CatmullRomCurve3(pts, true, 'catmullrom', 0.5)
    this.curve = curve
    const samples = this.quality === 'low' ? 320 : 520
    this.samples = curve.getSpacedPoints(samples)
    this.sampleCount = this.samples.length
    this.width = this.data.width || 18
    this.roadHalf = this.width / 2
    const width = this.width

    // road ribbon
    const verts = [], uvs = [], indices = []
    const N = this.samples.length
    for (let i = 0; i < N; i++) {
      const p = this.samples[i]
      const prev = this.samples[(i - 1 + N) % N]
      const next = this.samples[(i + 1) % N]
      const tx = next.x - prev.x, tz = next.z - prev.z
      const tl = Math.hypot(tx, tz) || 1
      const nx = -tz / tl, nz = tx / tl
      verts.push(p.x + nx * width / 2, 0, p.z + nz * width / 2)
      verts.push(p.x - nx * width / 2, 0, p.z - nz * width / 2)
      uvs.push(0, i / 6, 1, i / 6)
      if (i < N - 1) {
        const a = i * 2, b = i * 2 + 1, c = (i + 1) * 2, d = (i + 1) * 2 + 1
        indices.push(a, c, b, b, c, d)
      }
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3))
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2))
    geo.setIndex(indices)
    geo.computeVertexNormals()
    const roadTex = gridTexture(this.pal.grid, this.pal.grid2, 6, 256)
    roadTex.repeat.set(2, 1)
    const roadMat = new THREE.MeshStandardMaterial({
      color: this.pal.ground, map: roadTex, emissive: this.pal.grid, emissiveMap: roadTex,
      emissiveIntensity: 0.5, metalness: 0.8, roughness: 0.34,
    })
    const road = new THREE.Mesh(geo, roadMat)
    road.position.y = 0.01
    this.group.add(road)
    this.road = road

    // side neon rails + walls
    for (const side of [-1, 1]) {
      const railVerts = []
      const wallVerts = []
      for (let i = 0; i < N; i++) {
        const p = this.samples[i]
        const prev = this.samples[(i - 1 + N) % N]
        const next = this.samples[(i + 1) % N]
        const tx = next.x - prev.x, tz = next.z - prev.z
        const tl = Math.hypot(tx, tz) || 1
        const nx = -tz / tl, nz = tx / tl
        const x = p.x + nx * side * (width / 2 + 0.35)
        const z = p.z + nz * side * (width / 2 + 0.35)
        railVerts.push(x, 0.06, z)
        wallVerts.push(x, 0, z, x, 2.8, z)
        if (i < N - 1) {
          const a = i * 2, b = i * 2 + 1, c = (i + 1) * 2, d = (i + 1) * 2 + 1
        }
      }
      const rg = new THREE.BufferGeometry()
      rg.setAttribute('position', new THREE.Float32BufferAttribute(railVerts, 3))
      const lineGeo = new THREE.BufferGeometry().setFromPoints(
        this.samples.map((p, i) => {
          const prev = this.samples[(i - 1 + N) % N], next = this.samples[(i + 1) % N]
          const tx = next.x - prev.x, tz = next.z - prev.z, tl = Math.hypot(tx, tz) || 1
          return new THREE.Vector3(p.x - tz / tl * side * (width / 2 + 0.35), 0.08, p.z + tx / tl * side * (width / 2 + 0.35))
        }).concat([null]).filter(Boolean)
      )
      const line = new THREE.Line(lineGeo, new THREE.LineBasicMaterial({ color: side > 0 ? this.pal.accent : this.pal.accent2 }))
      this.group.add(line)
      // low glowing rail
      const rail = new THREE.Mesh(
        new THREE.TubeGeometry(new THREE.CatmullRomCurve3(lineGeo.attributes.position.array.length ? Array.from({ length: lineGeo.attributes.position.count }, (_, i) => new THREE.Vector3().fromBufferAttribute(lineGeo.attributes.position, i)) : []), false, 0.05, 4, N, true),
        new THREE.MeshBasicMaterial({ color: side > 0 ? this.pal.accent : this.pal.accent2 })
      )
      if (rail.geometry.attributes.position && rail.geometry.attributes.position.count > 0) this.group.add(rail)

      // wall ribbons
      const wg = new THREE.BufferGeometry()
      const wv = [], wi = []
      for (let i = 0; i < N; i++) {
        const p = this.samples[i]
        const prev = this.samples[(i - 1 + N) % N], next = this.samples[(i + 1) % N]
        const tx = next.x - prev.x, tz = next.z - prev.z, tl = Math.hypot(tx, tz) || 1
        const nx = -tz / tl, nz = tx / tl
        const x = p.x + nx * side * (width / 2 + 0.55)
        const z = p.z + nz * side * (width / 2 + 0.55)
        wv.push(x, 0, z, x, 2.6, z)
        if (i < N - 1) {
          const a = i * 2, b = i * 2 + 1, c = (i + 1) * 2, d = (i + 1) * 2 + 1
          wi.push(a, c, b, b, c, d)
        }
      }
      wg.setAttribute('position', new THREE.Float32BufferAttribute(wv, 3))
      wg.setIndex(wi)
      wg.computeVertexNormals()
      const wall = new THREE.Mesh(wg, new THREE.MeshStandardMaterial({
        color: this.pal.ground, metalness: 0.7, roughness: 0.5, transparent: true, opacity: 0.55,
        emissive: side > 0 ? this.pal.accent : this.pal.accent2, emissiveIntensity: 0.15, side: THREE.DoubleSide,
      }))
      this.group.add(wall)
    }

    // start line
    const startP = this.samples[0]
    const startNext = this.samples[3]
    const startHeading = Math.atan2(startNext.x - startP.x, startNext.z - startP.z)
    const lineTex = checkerTexture(this.pal.accent2, '#05070d')
    lineTex.repeat.set(width / 2, 1)
    const startLine = new THREE.Mesh(
      new THREE.PlaneGeometry(width, 2.4),
      new THREE.MeshBasicMaterial({ map: lineTex, transparent: true, opacity: 0.9 })
    )
    startLine.rotation.x = -Math.PI / 2
    startLine.rotation.z = -startHeading
    startLine.position.set(startP.x, 0.06, startP.z)
    this.group.add(startLine)

    // start gate arch
    this.addArch(startP.x, startP.z, startHeading, width + 6, this.pal.accent2, true)

    // checkpoint gates
    this.gates = []
    const gateCount = 5
    for (let i = 1; i <= gateCount; i++) {
      const idx = Math.floor((i / (gateCount + 1)) * N)
      const p = this.samples[idx], n = this.samples[(idx + 2) % N]
      const heading = Math.atan2(n.x - p.x, n.z - p.z)
      this.addArch(p.x, p.z, heading, width + 5, this.pal.accent)
      this.gates.push({ x: p.x, z: p.z, heading })
    }

    // boost pads
    const padTs = [0.12, 0.36, 0.61, 0.86]
    padTs.forEach((t, i) => {
      const idx = Math.floor(t * N)
      const p = this.samples[idx], n = this.samples[(idx + 3) % N]
      const heading = Math.atan2(n.x - p.x, n.z - p.z)
      const nx = Math.cos(heading), nz = -Math.sin(heading)
      const off = (i % 2 ? 1 : -1) * width * 0.2
      this.boostPads.push({ x: p.x + nx * off, z: p.z + nz * off, heading, r: 2.6 })
    })

    // off-road fill plane (large dark ground)
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(1400, 1400),
      new THREE.MeshStandardMaterial({ color: this.pal.sky, metalness: 0.4, roughness: 0.85 })
    )
    ground.rotation.x = -Math.PI / 2
    ground.position.y = -0.12
    this.group.add(ground)

    // center line dashes
    for (let i = 0; i < N; i += 12) {
      const p = this.samples[i], n = this.samples[(i + 6) % N]
      const heading = Math.atan2(n.x - p.x, n.z - p.z)
      const dash = new THREE.Mesh(new THREE.PlaneGeometry(0.16, 2.2), new THREE.MeshBasicMaterial({ color: this.pal.accent2, transparent: true, opacity: 0.55 }))
      dash.rotation.x = -Math.PI / 2; dash.rotation.z = -heading
      dash.position.set(p.x, 0.05, p.z)
      this.group.add(dash)
    }
  }

  addArch(x, z, heading, span, color, start = false) {
    const g = new THREE.Group()
    g.position.set(x, 0, z)
    g.rotation.y = heading
    const mat = new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 2.4, metalness: 0.5, roughness: 0.4 })
    const postGeo = new THREE.BoxGeometry(0.4, 6.5, 0.4)
    for (const sx of [-1, 1]) {
      const post = new THREE.Mesh(postGeo, mat)
      post.position.set(sx * span / 2, 3.25, 0)
      g.add(post)
    }
    const top = new THREE.Mesh(new THREE.BoxGeometry(span, 0.4, 0.4), mat)
    top.position.y = 6.5
    g.add(top)
    if (start) {
      const sign = new THREE.Mesh(new THREE.PlaneGeometry(span * 0.7, 1.2), new THREE.MeshBasicMaterial({
        map: this.makeTextTexture('NEON OVERDRIVE', color), transparent: true, side: THREE.DoubleSide,
      }))
      sign.position.set(0, 7.4, 0)
      g.add(sign)
    }
    this.group.add(g)
    return g
  }

  makeTextTexture(text, color) {
    const c = document.createElement('canvas')
    c.width = 512; c.height = 128
    const g = c.getContext('2d')
    g.fillStyle = 'rgba(2,6,14,0.75)'; g.fillRect(0, 0, 512, 128)
    g.strokeStyle = color; g.lineWidth = 5; g.shadowColor = color; g.shadowBlur = 16
    g.strokeRect(6, 6, 500, 116)
    g.fillStyle = color; g.font = 'bold 54px monospace'; g.textAlign = 'center'; g.textBaseline = 'middle'
    g.fillText(text, 256, 66)
    const tex = new THREE.CanvasTexture(c)
    tex.colorSpace = THREE.SRGBColorSpace
    return tex
  }

  // -------------------------------------------------------------------------
  // Shared environment decoration
  // -------------------------------------------------------------------------
  buildEnvironment() {
    const theme = this.data.theme
    const rnd = this.rnd
    const pal = this.pal
    const isCircuit = this.type === 'circuit'
    const extent = isCircuit ? 300 : Math.max(this.data.size.x, this.data.size.z) + 90
    const minR = isCircuit ? 0 : Math.max(this.data.size.x, this.data.size.z) * 1.15

    const addTower = (x, z, w, h, d, color) => {
      const mat = new THREE.MeshStandardMaterial({
        color: pal.ground, metalness: 0.85, roughness: 0.35,
        emissive: color, emissiveIntensity: 0.08,
      })
      const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat)
      m.position.set(x, h / 2, z)
      this.group.add(m)
      for (let y = 4; y < h; y += 8) {
        const line = new THREE.Mesh(new THREE.BoxGeometry(w + 0.3, 0.15, d + 0.3), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.65 }))
        line.position.set(x, y, z)
        this.group.add(line)
      }
      const top = new THREE.Mesh(new THREE.BoxGeometry(w * 0.4, 0.4, d * 0.4), new THREE.MeshBasicMaterial({ color }))
      top.position.set(x, h + 0.2, z)
      this.group.add(top)
    }

    if (['city', 'quantum', 'team', 'neon', 'highway', 'solar', 'tunnel'].includes(theme)) {
      const count = isCircuit ? 60 : 26
      for (let i = 0; i < count; i++) {
        const a = rnd() * Math.PI * 2
        const r = minR + (isCircuit ? 70 + rnd() * 200 : 55 + rnd() * 130)
        const w = 6 + rnd() * 16, h = 12 + rnd() * 65, d = 6 + rnd() * 16
        addTower(Math.cos(a) * r, Math.sin(a) * r, w, h, d, rnd() > 0.5 ? pal.accent : pal.accent2)
      }
      if (isCircuit) {
        // pylons along road
        const N = this.samples.length
        for (let i = 0; i < 24; i++) {
          const idx = Math.floor(i / 24 * N)
          const p = this.samples[idx], n = this.samples[(idx + 3) % N]
          const heading = Math.atan2(n.x - p.x, n.z - p.z)
          const side = i % 2 ? 1 : -1
          const off = this.width / 2 + 9
          const x = p.x + Math.cos(heading) * off * side
          const z = p.z - Math.sin(heading) * off * side
          const pylon = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.5, 9, 6), new THREE.MeshStandardMaterial({ color: pal.ground, metalness: 0.8, roughness: 0.4 }))
          pylon.position.set(x, 4.5, z)
          this.group.add(pylon)
          const light = neonBox(0.25, 0.25, 0.25, pal.accent)
          light.position.set(x, 9.1, z)
          this.group.add(light)
        }
      }
    }

    if (theme === 'forest') {
      for (let i = 0; i < 60; i++) {
        const a = rnd() * Math.PI * 2
        const r = minR + rnd() * 90
        const x = Math.cos(a) * r, z = Math.sin(a) * r
        const h = 8 + rnd() * 18
        const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.9, h, 6), new THREE.MeshStandardMaterial({ color: pal.ground, metalness: 0.5, roughness: 0.7, emissive: pal.accent, emissiveIntensity: 0.08 }))
        trunk.position.set(x, h / 2, z)
        this.group.add(trunk)
        for (let j = 0; j < 3; j++) {
          const cone = new THREE.Mesh(new THREE.ConeGeometry(4 - j, 5, 6), new THREE.MeshStandardMaterial({ color: pal.accent, emissive: pal.accent, emissiveIntensity: 0.35, transparent: true, opacity: 0.55, wireframe: j === 2 }))
          cone.position.set(x, h + j * 3, z)
          this.group.add(cone)
        }
      }
    } else if (theme === 'lava') {
      const lava = new THREE.Mesh(new THREE.PlaneGeometry(900, 900), new THREE.MeshBasicMaterial({ color: '#ff4d00', transparent: true, opacity: 0.14 }))
      lava.rotation.x = -Math.PI / 2; lava.position.y = -0.4
      this.group.add(lava)
      for (let i = 0; i < 40; i++) {
        const a = rnd() * Math.PI * 2, r = minR + rnd() * 120
        const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(2 + rnd() * 8), new THREE.MeshStandardMaterial({ color: '#1a0603', emissive: '#ff4d00', emissiveIntensity: 0.25, roughness: 0.9 }))
        rock.position.set(Math.cos(a) * r, 1, Math.sin(a) * r)
        rock.rotation.set(rnd() * 3, rnd() * 3, rnd() * 3)
        this.group.add(rock)
      }
    } else if (theme === 'ice') {
      for (let i = 0; i < 50; i++) {
        const a = rnd() * Math.PI * 2, r = minR + rnd() * 100
        const crystal = new THREE.Mesh(new THREE.ConeGeometry(1.5 + rnd() * 3, 6 + rnd() * 20, 5), new THREE.MeshStandardMaterial({ color: '#0e2a3d', emissive: '#67e8f9', emissiveIntensity: 0.3, metalness: 0.6, roughness: 0.2, transparent: true, opacity: 0.8 }))
        crystal.position.set(Math.cos(a) * r, 5, Math.sin(a) * r)
        crystal.rotation.z = (rnd() - 0.5) * 0.4
        this.group.add(crystal)
      }
    } else if (theme === 'space') {
      const planet = new THREE.Mesh(new THREE.SphereGeometry(90, 24, 16), new THREE.MeshStandardMaterial({ color: '#0b1a33', emissive: '#0e4a66', emissiveIntensity: 0.25, roughness: 0.8 }))
      planet.position.set(-220, 130, -260)
      this.group.add(planet)
      const ring = new THREE.Mesh(new THREE.TorusGeometry(140, 2, 6, 64), new THREE.MeshBasicMaterial({ color: '#22d3ee', transparent: true, opacity: 0.4 }))
      ring.position.copy(planet.position); ring.rotation.x = 1.1
      this.group.add(ring)
    } else if (theme === 'void') {
      for (let i = 0; i < 24; i++) {
        const a = rnd() * Math.PI * 2, r = minR + 40 + rnd() * 130
        const plat = new THREE.Mesh(new THREE.BoxGeometry(10 + rnd() * 20, 1.5, 10 + rnd() * 20), new THREE.MeshStandardMaterial({ color: pal.ground, metalness: 0.7, roughness: 0.4, emissive: pal.accent, emissiveIntensity: 0.15 }))
        plat.position.set(Math.cos(a) * r, -5 + rnd() * 30, Math.sin(a) * r)
        plat.rotation.y = rnd() * 3
        this.group.add(plat)
        const edge = neonBox(plat.geometry.parameters.width, 0.08, plat.geometry.parameters.depth, pal.accent)
        edge.position.copy(plat.position); edge.position.y += 0.8; edge.rotation.y = plat.rotation.y
        this.group.add(edge)
      }
    } else if (theme === 'desert') {
      for (let i = 0; i < 36; i++) {
        const a = rnd() * Math.PI * 2, r = minR + rnd() * 150
        const dune = new THREE.Mesh(new THREE.SphereGeometry(8 + rnd() * 20, 8, 6, 0, Math.PI * 2, 0, Math.PI / 2), new THREE.MeshStandardMaterial({ color: '#241305', emissive: '#f59e0b', emissiveIntensity: 0.08, roughness: 0.95 }))
        dune.position.set(Math.cos(a) * r, -1, Math.sin(a) * r)
        dune.scale.y = 0.4
        this.group.add(dune)
      }
    } else if (theme === 'underground' || theme === 'ruin') {
      for (let i = 0; i < 30; i++) {
        const a = rnd() * Math.PI * 2, r = minR + 40 + rnd() * 110
        const h = 10 + rnd() * 45
        const pillar = new THREE.Mesh(new THREE.CylinderGeometry(2 + rnd() * 4, 3 + rnd() * 5, h, 6), new THREE.MeshStandardMaterial({ color: pal.ground, metalness: 0.7, roughness: 0.6, emissive: pal.accent, emissiveIntensity: 0.06 }))
        pillar.position.set(Math.cos(a) * r, h / 2 - 2, Math.sin(a) * r)
        this.group.add(pillar)
        const stripe = neonBox(0.15, 0.15, 8, pal.accent)
        stripe.position.set(Math.cos(a) * r, h * 0.6, Math.sin(a) * r)
        stripe.rotation.y = rnd() * 3
        this.group.add(stripe)
      }
    }

    // floating dust / data motes
    const moteCount = this.quality === 'low' ? 120 : 320
    const pos = new Float32Array(moteCount * 3)
    for (let i = 0; i < moteCount; i++) {
      pos[i * 3] = (rnd() - 0.5) * extent * 2
      pos[i * 3 + 1] = rnd() * 40 + 1
      pos[i * 3 + 2] = (rnd() - 0.5) * extent * 2
    }
    const pg = new THREE.BufferGeometry()
    pg.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    this.motes = new THREE.Points(pg, new THREE.PointsMaterial({
      color: pal.accent, size: 0.35, transparent: true, opacity: 0.55,
      blending: THREE.AdditiveBlending, depthWrite: false,
    }))
    this.group.add(this.motes)

    if (this.enclosed) {
      const ceiling = new THREE.Mesh(new THREE.PlaneGeometry(1400, 1400), new THREE.MeshBasicMaterial({ color: pal.sky, side: THREE.DoubleSide }))
      ceiling.rotation.x = Math.PI / 2
      ceiling.position.y = 34
      this.group.add(ceiling)
      for (let i = 0; i < 30; i++) {
        const a = rnd() * Math.PI * 2, r = minR + rnd() * 120
        const ring = new THREE.Mesh(new THREE.TorusGeometry(4 + rnd() * 8, 0.3, 6, 24), new THREE.MeshBasicMaterial({ color: pal.accent, transparent: true, opacity: 0.35 }))
        ring.position.set(Math.cos(a) * r, 20 + rnd() * 12, Math.sin(a) * r)
        ring.rotation.x = Math.PI / 2
        this.group.add(ring)
      }
    }
  }

  addBoostPads() {
    for (const p of this.boostPads) {
      const g = new THREE.Group()
      g.position.set(p.x, 0.08, p.z)
      g.rotation.y = p.heading
      const mat = new THREE.MeshBasicMaterial({ color: this.pal.accent2, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, side: THREE.DoubleSide })
      for (let i = 0; i < 3; i++) {
        const chev = new THREE.Mesh(new THREE.PlaneGeometry(3.2, 0.6), mat)
        chev.rotation.x = -Math.PI / 2
        chev.position.z = i * 1.3 - 1.2
        g.add(chev)
      }
      const ring = new THREE.Mesh(new THREE.TorusGeometry(2.2, 0.06, 5, 24), mat)
      ring.rotation.x = Math.PI / 2
      g.add(ring)
      this.group.add(g)
      p.mesh = g
    }
  }

  // -------------------------------------------------------------------------
  // Queries
  // -------------------------------------------------------------------------
  inside(x, z, scale = this.shrinkScale) {
    if (this.type === 'circuit') {
      const q = this.closest(x, z)
      return q.dist < this.roadHalf - 0.7
    }
    if (scale >= 0.999) return insidePoly(x, z, this.poly)
    return insidePoly(x / scale, z / scale, this.poly)
  }

  closest(x, z) {
    if (this.type !== 'circuit') return { dist: 0, t: 0, index: 0, x, z }
    let best = Infinity, bi = 0
    const S = this.samples
    for (let i = 0; i < S.length; i += 2) {
      const p = S[i]
      const d = (p.x - x) * (p.x - x) + (p.z - z) * (p.z - z)
      if (d < best) { best = d; bi = i }
    }
    // refine neighbours
    for (let i = Math.max(0, bi - 3); i < Math.min(S.length, bi + 4); i++) {
      const p = S[i]
      const d = (p.x - x) * (p.x - x) + (p.z - z) * (p.z - z)
      if (d < best) { best = d; bi = i }
    }
    const p = S[bi], n = S[(bi + 1) % S.length]
    return { dist: Math.sqrt(best), t: bi / S.length, index: bi, x: p.x, z: p.z, tangent: Math.atan2(n.x - p.x, n.z - p.z) }
  }

  wallDistance(x, z) {
    if (this.type === 'circuit') return this.roadHalf - this.closest(x, z).dist
    // approximate arena wall distance via polygon edges
    let best = Infinity
    const scale = this.shrinkScale
    for (let i = 0; i < this.poly.length; i++) {
      const a = this.poly[i], b = this.poly[(i + 1) % this.poly.length]
      best = Math.min(best, distToSegment(x, z, a[0] * scale, a[1] * scale, b[0] * scale, b[1] * scale))
    }
    return best
  }

  hitObstacle(x, z, radius = 0.7) {
    for (const o of this.obstacles) {
      const hw = o.w / 2 + radius, hd = o.d / 2 + radius
      if (Math.abs(x - o.x) < hw && Math.abs(z - o.z) < hd) return o
    }
    return null
  }

  hazardAt(x, z) {
    for (const h of this.hazards) {
      if (!h.active) continue
      if (Math.hypot(x - h.x, z - h.z) < h.r) return h
    }
    return null
  }

  boostPadAt(x, z) {
    for (const p of this.boostPads) {
      if (Math.hypot(x - p.x, z - p.z) < p.r) return p
    }
    return null
  }

  getStartPositions(count) {
    const out = []
    if (this.type === 'circuit') {
      const N = this.samples.length
      const base = N - 4
      for (let i = 0; i < count; i++) {
        const row = Math.floor(i / 2)
        const col = i % 2
        const idx = (base - row * 6 + N * 2) % N
        const p = this.samples[idx]
        const n = this.samples[(idx + 2) % N]
        const heading = Math.atan2(n.x - p.x, n.z - p.z)
        const nx = Math.cos(heading), nz = -Math.sin(heading)
        const off = (col === 0 ? -1 : 1) * (this.width * 0.18)
        out.push({ x: p.x + nx * off, z: p.z + nz * off, heading, t: idx / N })
      }
      return out
    }
    const r = Math.min(this.data.size.x, this.data.size.z) * 0.62
    for (let i = 0; i < count; i++) {
      const a = Math.PI / 2 + (i / Math.max(1, count)) * Math.PI * 2
      const x = Math.cos(a) * r, z = Math.sin(a) * r
      const heading = a + Math.PI / 2
      out.push({ x, z, heading, t: 0 })
    }
    return out
  }

  getMinimap() {
    if (this.type === 'circuit') {
      return { type: 'circuit', points: this.samples.filter((_, i) => i % 8 === 0).map(p => [p.x, p.z]), width: this.width }
    }
    return { type: 'arena', points: this.poly, size: this.data.size, shape: this.data.shape }
  }

  setShrink(scale) {
    this.shrinkScale = Math.max(0.45, Math.min(1, scale))
    if (this.wallGroup) this.wallGroup.scale.set(this.shrinkScale, 1, this.shrinkScale)
    if (this.shrinkRing) {
      this.shrinkRing.visible = this.shrinkScale < 0.995
      const r = Math.max(this.data.size.x, this.data.size.z) * this.shrinkScale
      this.shrinkRing.scale.set(r, r, r)
      this.shrinkRing.rotation.z = this.time * 0.3
    }
  }

  update(dt) {
    this.time += dt
    const t = this.time
    for (const h of this.hazards) {
      if (h.period > 0) {
        const cycle = (t + h.phase) % h.period
        h.active = cycle < h.period * 0.55
        const pulse = 0.35 + Math.sin(t * 4 + h.phase) * 0.15 + (h.active ? 0.35 : 0)
        h.disc.material.opacity = h.active ? 0.2 + Math.sin(t * 6) * 0.08 : 0.05
        h.ring.material.opacity = h.active ? 0.9 : 0.25
        h.mesh.scale.setScalar(1 + (h.active ? Math.sin(t * 3 + h.phase) * 0.02 : 0))
      }
    }
    for (const p of this.boostPads) {
      if (p.mesh) p.mesh.children.forEach((c, i) => {
        if (c.material) c.material.opacity = 0.55 + Math.sin(t * 6 - i) * 0.35
      })
    }
    if (this.motes) this.motes.rotation.y += dt * 0.01
    if (this.roadTex) this.roadTex.offset.y -= dt * 0.02
  }

  dispose() {
    this.scene.remove(this.group)
    this.group.traverse(o => {
      if (o.geometry) o.geometry.dispose()
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach(m => { if (m.map) m.map.dispose(); m.dispose() })
        else { if (o.material.map) o.material.map.dispose(); o.material.dispose() }
      }
    })
    for (const l of this.lights || []) this.scene.remove(l)
  }
}

export { polygonFor, insidePoly, distToSegment }

