      return new THREE.Vector3(p.x - tz / tl * side * (width / 2 + 0.35), 0.08, p.z + tx / tl * side * (width / 2 + 0.35))
    }).concat([null]).filter(Boolean)
  )
  const line = new THREE.Line(lineGeo, new THREE.LineBasicMaterial({ color: side > 0 ? this.pal.accent : this.pal.accent2 }))
  this.group.add(line)
  // low glowing rail
  const rail = new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(lineGeo.attributes.position.array.length ? Array.from({ length: lineGeo.attributes.position.count }, (_, i) => new THREE.Vector3().fromBufferAttribute(lineGeo.attributes.position, i)) : []), false, 0.05, 4, N, true),
    new THREE.MeshBasicMaterial({ color: side > 0 ? this.pal.accent : this.pal.accent2 })
  )
  if (rail.geometry.attributes.position && rail.geometry.attributes.position.count > 0) this.group.add(rail)

  // wall ribbons
  const wg = new THREE.BufferGeometry()
  const wv = [], wi = []
  for (let i = 0; i < N; i++) {
    const p = this.samples[i]
    const prev = this.samples[(i - 1 + N) % N], next = this.samples[(i + 1) % N]
    const tx = next.x - prev.x, tz = next.z - prev.z, tl = Math.hypot(tx, tz) || 1
    const nx = -tz / tl, nz = tx / tl
    const x = p.x + nx * side * (width / 2 + 0.55)
    const z = p.z + nz * side * (width / 2 + 0.55)
    wv.push(x, 0, z, x, 2.6, z)
    if (i < N - 1) {
      const a = i * 2, b = i * 2 + 1, c = (i + 1) * 2, d = (i + 1) * 2 + 1
      wi.push(a, c, b, b, c, d)
    }
  }
  wg.setAttribute('position', new THREE.Float32BufferAttribute(wv, 3))
  wg.setIndex(wi)
  wg.computeVertexNormals()
  const wall = new THREE.Mesh(wg, new THREE.MeshStandardMaterial({
    color: this.pal.ground, metalness: 0.7, roughness: 0.5, transparent: true, opacity: 0.55,
    emissive: side > 0 ? this.pal.accent : this.pal.accent2, emissiveIntensity: 0.15, side: THREE.DoubleSide,
  }))
  this.group.add(wall)
}

