  .steer-btn { width: 62px; height: 62px; }
  .steer-pad { bottom: calc(76px + env(safe-area-inset-bottom)); }
  .action-pad { bottom: calc(76px + env(safe-area-inset-bottom)); }
  .collection-grid { grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); }
  .achievement-grid { grid-template-columns: 1fr 1fr; }
  .menu-screen .screen { background: linear-gradient(180deg, rgba(2, 6, 14, 0.9) 0%, rgba(2, 6, 14, 0.5) 55%, rgba(2, 6, 14, 0.92) 100%); }
  .event-row { grid-template-columns: 28px 1fr auto; }
  .event-pts { display: none; }
}
@media (orientation: portrait) and (max-width: 820px) {
  #rotate-hint { display: block !important; }
  .menu-screen { background: linear-gradient(180deg, rgba(2, 6, 14, 0.9), rgba(2, 6, 14, 0.45) 50%, rgba(2, 6, 14, 0.95)); }
}
@media (hover: none) and (pointer: coarse) {
  .touch-controls.show { display: block; }
}

