let last = performance.now()
function frame(now) {
  const dt = clamp((now - last) / 1000, 0, 0.05)
  last = now
  fpsAccum += dt
  fpsFrames += 1
  if (fpsAccum >= 0.5) {
    fpsAccum = fpsFrames / fpsAccum
    fpsFrames = 0
  }
  if (state.game && state.screen !== 'results') {
    if (!state.game.paused) state.game.update(dt)
    state.game.render()
    if (state.profile.settings.showFps && fpsEl) {
      fpsEl.textContent = `${Math.round(fpsAccum)} FPS • ${resolveQuality().toUpperCase()}`
    }
  } else if (preview) {
    preview.update(dt)
    preview.render()
  }
  requestAnimationFrame(frame)
}

