import { createRequire } from 'node:module'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const browser = await chromium.launch({ headless: true, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 800, height: 500 } })
page.on('pageerror', e => console.log('[pageerror]', e.message))
await page.goto('http://localhost:8000/', { waitUntil: 'load' })
await page.waitForSelector('#boot-enter:not(.hidden)', { timeout: 20000 })
await page.click('#boot-enter')
await page.waitForTimeout(500)
const rafOnly = await page.evaluate(() => new Promise(resolve => {
 let n=0, prev=performance.now(), deltas=[]
 function f(t){ n++; deltas.push(t-prev); prev=t; if(t-deltas[0] < 2000) requestAnimationFrame(f); else resolve({n,avg:deltas.reduce((a,b)=>a+b,0)/deltas.length, max:Math.max(...deltas), deltas:deltas.slice(0,20)}) }
 requestAnimationFrame(f)
}))
console.log('menu raf', rafOnly)
await page.evaluate(() => { const s=window.__NEON_OVERDRIVE__; s.profile.settings.quality='low' })
await page.click('[data-action="nav"][data-screen="modes"]')
await page.waitForTimeout(100)
await page.click('[data-action="select-mode"][data-mode="classic"]')
await page.waitForTimeout(100)
await page.click('[data-action="start-race"]')
await page.waitForTimeout(1000)
const started = await page.evaluate(() => {
 const g=window.__NEON_OVERDRIVE__.game
 const oldR=g.render.bind(g), oldU=g.update.bind(g)
 let rc=0,uc=0,rt=0,ut=0
 g.render=()=>{const t=performance.now();oldR();rt+=performance.now()-t;rc++}
 g.update=(dt)=>{const t=performance.now();oldU(dt);ut+=performance.now()-t;uc++}
 return {quality:g.quality,phase:g.phase,window:{w:innerWidth,h:innerHeight},dpr:devicePixelRatio}
})
await page.waitForTimeout(4000)
const result = await page.evaluate(() => {const g=window.__NEON_OVERDRIVE__.game;return {phase:g.phase,intro:g.introTime, fpsText:document.querySelector('#hud-fps')?.textContent, calls:g.renderer.info.render.calls,tris:g.renderer.info.render.triangles}})
console.log('game before',started,'after',result)
await browser.close()

